{
  "_comment": "SOCKET.IO EVENT — Use Postman's Socket.IO tab to emit this",
  "event": "send-message",
  "payload": {
    "chatId": "{{chatId}}",
    "content": "Hello from Postman!",
    "messageType": "text",
    "attachmentUrl": null,
    "replyTo": null
  },
  "payload_for_new_direct_chat": {
    "receiverId": "{{userId}}",
    "content": "Hey! First message",
    "messageType": "text"
  },
  "note": "senderId is auto-extracted from JWT. Use either chatId (existing chat) OR receiverId (new direct chat)."
}

{
  "_comment": "SOCKET.IO EVENT — Use Postman's Socket.IO tab to emit this",
  "event": "edit-message",
  "payload": {
    "messageId": "{{messageId}}",
    "chatId": "{{chatId}}",
    "newContent": "Edited message content"
  },
  "note": "Only the original sender can edit. Validated via JWT."
}

{
  "_comment": "SOCKET.IO EVENT — Use Postman's Socket.IO tab to emit this",
  "event": "delete-message",
  "payload": {
    "messageId": "{{messageId}}",
    "chatId": "{{chatId}}"
  },
  "note": "Soft delete — sets isDeleted=true and clears content. Only sender can delete."
}

{
  "_comment": "SOCKET.IO EVENT with ACK CALLBACK — Use Postman's Socket.IO tab",
  "event": "get-messages",
  "payload": {
    "chatId": "{{chatId}}",
    "page": 1,
    "limit": 50
  },
  "note": "Returns data via acknowledgement callback, not emit."
}

{
  "_comment": "SOCKET.IO EVENT — Use Postman's Socket.IO tab to emit this",
  "event": "typing",
  "payload_for_direct": {
    "receiverId": "{{userId}}"
  },
  "payload_for_group": {
    "chatId": "{{chatId}}"
  },
  "note": "Use receiverId for direct chats, chatId for group chats."
}
